L.def('cc.disputes',{render:(c)=>{ const s=S(); const A=s.disputes.filter(d=>c.v==='done'?d.st!=='open':d.st==='open'); return A.length?H.sec('',H.rows(A.map(d=>({ic:'flag',tone:d.st==='open'?'warn':'ok',t:`${LTR(d.id)} · ${t('Al Wadi Restaurant','مطعم الوادي')}`,s:`${LTR(d.inv)} · ${M(L.dispAmt(d))} · ${ago(d.ts)}`,pill:L.dPill(d),go:'cc.disputeCase',q:{id:d.id}})))):H.empty('inbox',c.v==='done'?t('No decisions yet','لا قرارات بعد'):t('No disputes waiting','لا اعتراضات بالانتظار'),t('Customers question invoice lines from the invoice screen.','يعترض العملاء على بنود الفاتورة من شاشة الفاتورة.'),c.v==='done'?'':H.btns(L.ab(t('Try it: sign in as the owner','جرّب: ادخل كمالك'),'login','owner',{k:'sec'}))); }});
