L.def('cc.disputeCase',{v:null,noSeg:true,t:()=>t('Dispute','اعتراض')+' '+(qp('id')||'C-2294'),render:(c)=>{ const d=S().disputes.find(x=>x.id===(qp('id')||'C-2294'))||S().disputes[0]; if(!d) return H.empty('inbox',t('Dispute not found','الاعتراض غير موجود'),''); const amt=L.dispAmt(d); const i=S().invoices.find(x=>x.no===d.inv); const dc=L.ui.dc[d.id]=L.ui.dc[d.id]||{k:'accept'}; const big=amt>10000;
 let h=H.sec('',`<div class="card pad"><div class="sla"><span class="l"><b>${t('Al Wadi Restaurant','مطعم الوادي')} · ${LTR(d.inv)}</b>${H.pill(...L.dPill(d))}</span><span class="why">${t('Raised','رُفع')} ${ago(d.ts)} · ${t('reminders paused on','التذكيرات متوقفة على')} ${M(amt)}</span></div></div>`,{raw:true});
 h+=H.sec(t('Disputed lines','البنود المعترض عليها'),H.table([t('Item','الصنف'),t('Qty','الكمية'),t('Billed','المفوتر'),t('Expected','المتوقع'),t('Diff incl. VAT','الفرق شامل الضريبة')],d.lines.map(l=>[pn(l.sku),N(l.q),M(l.billed),M(l.exp),M(r2((l.billed-l.exp)*l.q*1.15))]),t('Disputed lines','البنود المعترض عليها')),{raw:true});
 h+=H.sec(t('Check','التحقق'),H.kv([[t('Contract price list (sample)','قائمة أسعار العقد (تجريبية)'),d.lines.map(l=>`${pn(l.sku).split(' ')[0]} ${M(l.exp)}`).join(' · ')],[t('Invoice balance','رصيد الفاتورة'),i?M(L.bal(i)):'—'],[t('Customer note','ملاحظة العميل'),esc(T2(d.note||['—','—']))||'—']]));
 if(d.st!=='open') return h+H.alert(d.st==='rejected'?'bad':'ok',L.dPill(d)[1],d.cn?`${t('Credit note','إشعار دائن')} ${LTR(d.cn)} · ${M(-d.credit)} ${t('applied to','طُبّق على')} ${LTR(d.inv)}`:esc(T2(d.reason||['',''])));
 if(!['acct','mgr'].includes(c.role)) return h;
 h+=H.sec(t('Decision','القرار'),L.radio('dck',[['accept',t('Accept in full','قبول كامل'),t('Credit note for','إشعار دائن بمبلغ')+' '+M(amt)],['partial',t('Accept part','قبول جزئي'),t('Enter the amount to credit','أدخل مبلغ الإشعار')],['reject',t('Reject','رفض'),t('Reminders restart with 2 days’ grace','تُستأنف التذكيرات مع مهلة يومين')]],dc.k,t('Decision','القرار'))+`<div style="padding:4px 16px 12px">${dc.k==='partial'?L.fld('dcamt',t('Credit amount incl. VAT','مبلغ الإشعار شامل الضريبة'),{req:true,pre:'SAR',ltr:true,im:'decimal',val:dc.amt||''}):''}${L.fld('dcnote',dc.k==='reject'?t('Reason (shown to the customer)','السبب (يظهر للعميل)'):t('Note (optional)','ملاحظة (اختياري)'),{ta:true,req:dc.k==='reject',val:dc.note||''})}</div>`);
 h+=H.lock(big?t('Over SAR 10,000: the accountant recommends and a manager approves.','أكثر من 10,000: يوصي المحاسب ويعتمد المدير.'):t('Up to SAR 10,000: the accountant can approve the credit note.','حتى 10,000: يمكن للمحاسب اعتماد الإشعار الدائن.'),'shield');
 return {b:h,dock:L.ab(big&&c.role==='acct'?t('Recommend to manager','أوصِ للمدير'):t('Confirm decision','أكّد القرار'),'dcgo',d.id,{block:true})}; }});
const dcKeep=id=>{ const dc=L.ui.dc[id]; const a=document.querySelector('[name=dcamt]'), n=document.querySelector('[name=dcnote]'); if(a) dc.amt=a.value; if(n) dc.note=n.value; };
