ACT.dcgo=id=>{ dcKeep(id); L.clearBad(); const s=S(); const d=s.disputes.find(x=>x.id===id); const dc=L.ui.dc[id]; const full=L.dispAmt(d); let amt=0;
 if(dc.k==='accept') amt=full; if(dc.k==='partial'){ amt=Number(String(dc.amt||'').replace(',','.')); if(!(amt>0)||amt>=full){ L.bad('dcamt',t(`Enter more than 0 and less than ${full.toFixed(2)}`,`أدخل أكثر من 0 وأقل من ${full.toFixed(2)}`)); L.focusBad(); return; } }
 if(dc.k==='reject'&&!(dc.note||'').trim()){ L.bad('dcnote',t('Give the customer a reason','اذكر السبب للعميل')); L.focusBad(); return; }
 if(full>10000&&MF.C.role==='acct'){ d.rec={k:dc.k,amt,ts:now()}; L.save(); toast(t('Recommended · sent to the manager','أُرسلت التوصية للمدير')); go('cc.disputes'); return; }
 const i=s.invoices.find(x=>x.no===d.inv);
 if(dc.k==='reject'){ d.st='rejected'; d.reason=[dc.note,dc.note]; if(i) i.due=Math.max(i.due,now()+2*DAY); }
 else { const no='CN-2026-0'+(++s.seq.cn); d.cn=no; d.credit=r2(amt); d.st=dc.k==='accept'?'accepted':'partial'; if(i) i.cr=r2((i.cr||0)+amt); s.cns.unshift({no,inv:d.inv,amt:r2(amt),ts:now(),why:[`Dispute ${d.id}`,`الاعتراض ${d.id}`]}); }
 d.by2=MF.C.role; d.dts=now(); L.notify('flag',[`Dispute ${d.id}: ${d.st==='rejected'?'rejected':'credit note '+d.cn}`,`الاعتراض ${d.id}: ${d.st==='rejected'?'مرفوض':'إشعار دائن '+d.cn}`],['cc.ticket',{id:d.id}]); delete L.ui.dc[id]; L.save(); L.rr(); toast(d.st==='rejected'?t('Dispute rejected · customer notified','رُفض الاعتراض · أُبلغ العميل'):t(`Credit note ${d.cn} issued`,`صدر الإشعار الدائن ${d.cn}`)); };

