 h+=H.sec(t('Conversation','المحادثة'),`<div class="chat" style="margin:0">${x.ev.filter(e=>e.txt||e.k==='recv').map(e=>{ const txt=e.k==='recv'?(typeof x.txt==='string'?esc(x.txt):T2(x.txt)):(Array.isArray(e.txt)?T2(e.txt):esc(e.txt)); if(e.who==='sys'&&e.k!=='recv') return `<p class="sysm">${txt}</p>`; if(e.who==='note') return bub('note',`<b>${t('Internal note','ملاحظة داخلية')}</b> ${txt}`,e.ts); if(e.who==='me'||e.k==='recv') return who(t('F','ف'),t('Faisal · customer','فيصل · العميل'))+bub('',txt,e.ts); return bub('me',txt,e.ts); }).join('')}</div>`,{raw:true});
