/* ---------- BUSINESS HUB & CASH BOOK ---------- */
const CAT={supplies:['Supplies','مستلزمات'],utilities:['Utilities','خدمات'],rent:['Rent','إيجار'],salaries:['Staff & wages','الموظفون والأجور'],maint:['Repairs','صيانة'],transport:['Transport','نقل'],other:['Other','أخرى']};
const catL=k=>T2(CAT[k]||CAT.other);
const startToday=()=>{ const d=new Date(); d.setHours(0,0,0,0); return d.getTime(); };
const cashBal=()=>{ const s=S(); return r2(s.hub.cash.reduce((a,e)=>a+(e.k==='open'?e.amt:e.k==='sale'&&e.m==='cash'?e.amt:(e.k==='exp'||e.k==='sup')&&e.m!=='card'?-e.amt:0),0)); };
L.cashBal=cashBal;
const hubK=()=>{ const s=S(); const m0=(()=>{ const d=new Date(); d.setDate(1); d.setHours(0,0,0,0); return d.getTime(); })(); const exp=r2(s.hub.exp.filter(e=>e.ts>=m0).reduce((a,e)=>a+e.amt,0)); const owe=r2(s.hub.bills.reduce((a,b)=>a+Math.max(0,b.amt-b.paid),0)); const sales=r2(s.hub.cash.filter(e=>e.k==='sale'&&e.ts>=startToday()).reduce((a,e)=>a+e.amt,0)); return {exp,owe,sales,cash:cashBal()}; };
L.def('bh.home',{v:null,noSeg:true,render:(c)=>{ const s=S(), k=hubK(); const recent=[...s.hub.exp.map(e=>({ts:e.ts,ic:'receipt',t:`${catL(e.cat)} · ${esc(T2(e.note))}`,v:-e.amt,go:'bh.expenses'})),...s.hub.cash.filter(e=>e.k==='sale').map(e=>({ts:e.ts,ic:'cash',t:`${t('Sale','بيع')} · ${e.m==='cash'?t('cash','نقدًا'):e.m}`,v:e.amt,go:'cb.today'})),...s.hub.bills.filter(b=>b.paidTs).map(b=>({ts:b.paidTs,ic:'wallet',t:`${t('Paid','دُفع')} ${esc(T2(b.sup))}`,v:-b.lastPay,go:'bh.payments'}))].sort((a,b)=>b.ts-a.ts).slice(0,5);
 return H.kpis([[t('Sales today','مبيعات اليوم'),M(k.sales,'',0)],[t('Cash in drawer','النقد في الدرج'),M(k.cash,'',0)],[t('Expenses this month','مصروفات الشهر'),M(k.exp,'',0)],[t('You owe suppliers','مستحق للموردين'),M(k.owe,'',0),'',k.owe?'warn':'']])
 +H.sec(t('Quick actions','إجراءات سريعة'),`<div class="tiles">${[['receipt',t('Add expense','أضف مصروفًا'),'bh.expense'],['cash',t('Cash sale','بيع نقدي'),'cb.sale'],['wallet',t('Pay a supplier','ادفع لمورد'),'bh.payments'],['doc',t('Cash book','دفتر النقدية'),'cb.today']].map(([ic,l,g])=>`<a class="tile" href="${href(g)}"><span class="ti">${I(ic,22)}</span><span class="tl1">${l}</span></a>`).join('')}</div>`,{raw:true})
 +H.sec(t('Recent activity','آخر النشاط'),recent.length?H.rows(recent.map(r=>({ic:r.ic,tone:r.v<0?'':'ok',t:r.t,s:ago(r.ts),end:M(r.v),go:r.go}))):`<div style="padding:8px 0">${H.note(t('Nothing yet today.','لا شيء بعد اليوم.'))}</div>`)
 +H.sec('',H.rows([{ic:'chart',tone:'brand',t:t('Reports','التقارير'),s:t('Prototype screens','شاشات نموذجية'),go:'bh.reports'},{ic:'calendar',tone:'brand',t:t('25-day forecast','توقع 25 يومًا'),s:t('Prototype screens','شاشات نموذجية'),go:'bh.forecast'}])); }});
