L.def('bh.expenses',{render:(c)=>{ const s=S(); const f=L.ui.expf; const A=s.hub.exp.filter(e=>f==='all'||e.cat===f).sort((a,b)=>b.ts-a.ts); const tot=r2(A.reduce((a,e)=>a+e.amt,0));
 return L.chipsA('expf',[['all',t('All','الكل')]].concat(Object.keys(CAT).filter(k=>s.hub.exp.some(e=>e.cat===k)).map(k=>[k,catL(k)])),f,t('Category','الفئة'))+H.sec(t(`${A.length} expenses`,`${A.length} مصروفات`),A.length?H.rows(A.map(e=>({ic:'receipt',t:`${catL(e.cat)} · ${esc(T2(e.note))||'—'}`,s:`${dt(e.ts)} · ${e.m==='card'?t('card','بطاقة'):e.m==='bank'?t('bank','بنك'):t('cash','نقد')}${e.by==='cashier'?' · '+t('by Mona','بواسطة منى'):''}`,end:`<span class="lv-row-e">${M(e.amt)}<button type="button" class="ib flat" data-act="expdel" data-arg="${e.id}" aria-label="${t('Delete expense','احذف المصروف')}">${I('trash',18)}</button></span>`}))):`<div style="padding:8px 0">${H.note(t('No expenses in this category.','لا مصروفات في هذه الفئة.'))}</div>`,{right:`<b class="lv-tot">${M(tot)}</b>`}); }});
