L.def('bh.expense',{v:null,noSeg:true,render:(c)=>H.sec('',expForm(c,false))+H.sec(t('Paid from','دُفع من'),L.radio('em',[['cash',t('Cash drawer','درج النقد'),t('Also recorded in the cash book','يُسجل أيضًا في دفتر النقدية')],['card',t('Business card','بطاقة المنشأة')],['bank',t('Bank transfer','تحويل بنكي')]],'cash',t('Paid from','دُفع من')))+H.sec('',`<div style="padding:12px 16px">${H.btns(L.ab(t('Attach receipt (simulated)','أرفق الإيصال (محاكاة)'),'erc',null,{k:'sec',sm:true,ic:'camera'}))}<p class="why" id="ercs">${L.ui.erc?t('Receipt photo attached','أُرفقت صورة الإيصال'):''}</p></div>`)+H.btns(L.ab(t('Save expense','احفظ المصروف'),'esave','hub'))});
