ACT.erc=()=>{ L.ui.erc=true; const p=document.getElementById('ercs'); if(p) p.textContent=t('Receipt photo attached','أُرفقت صورة الإيصال'); toast(t('Receipt attached','أُرفق الإيصال')); };
const amtOf=n=>Number(String(L.val(n)).replace(/[, ]/g,'').replace('٫','.'));
ACT.esave=src=>{ L.clearBad(); const amt=amtOf('eamt'); const note=L.val('enote'); let ok=true; if(!(amt>0)){ L.bad('eamt',t('Enter an amount above 0','أدخل مبلغًا أكبر من 0')); ok=false; } else if(amt>100000){ L.bad('eamt',t('That looks too high — max 100,000','المبلغ مرتفع — الحد 100,000')); ok=false; } if(!note){ L.bad('enote',t('Say what it was for','اذكر الغرض')); ok=false; } if(!ok){ L.focusBad(); return; }
 const s=S(); const m=src==='cash'?'cash':(L.val('em')||'cash'); const d=L.val('edate'); const ts=d?new Date(d+'T12:00').getTime():now(); const id='E'+(++s.seq.exp);
 if(m==='cash'&&amt>cashBal()){ L.bad('eamt',t(`Only ${cashBal().toFixed(2)} in the drawer`,`يوجد ${cashBal().toFixed(2)} فقط في الدرج`)); L.focusBad(); return; }
 s.hub.exp.unshift({id,ts:Math.min(ts,now()),amt:r2(amt),cat:L.val('ecat')||'other',note:[note,note],by:MF.C.role,m,rc:!!L.ui.erc}); if(m==='cash') s.hub.cash.push({id:'K'+(++s.seq.cash),ts:now(),k:'exp',amt:r2(amt),m:'cash',cat:L.val('ecat'),note:[note,note],ref:id}); L.ui.erc=false; L.save();
 go(src==='cash'?'cb.today':'bh.expenses'); setTimeout(()=>toast(t(`Expense saved · ${amt.toFixed(2)}`,`حُفظ المصروف · ${amt.toFixed(2)}`)),80); };
L.def('bh.payments',{v:null,noSeg:true,render:(c)=>{ const s=S(); const open=s.hub.bills.filter(b=>b.amt-b.paid>0).sort((a,b)=>a.due-b.due); const done=s.hub.bills.filter(b=>b.amt-b.paid<=0); const owe=r2(open.reduce((a,b)=>a+b.amt-b.paid,0));
 return H.kpis([[t('You owe','عليك'),M(owe),t(`${open.length} bills`,`${open.length} فواتير`),owe?'warn':''],[t('Overdue','متأخر'),M(r2(open.filter(b=>b.due<now()).reduce((a,b)=>a+b.amt-b.paid,0)))]])
 +H.sec(t('To pay','للدفع'),open.length?open.map(b=>H.row({ic:'store',tone:b.due<now()?'bad':'brand',t:esc(T2(b.sup)),s:`${b.due<now()?t('Overdue since','متأخرة منذ'):t('Due','تستحق')} ${dt(b.due)}${b.paid?' · '+t('paid','مدفوع')+' '+b.paid.toFixed(2):''}`,end:`<span class="lv-row-e">${M(b.amt-b.paid)}${L.ab(t('Pay','ادفع'),'billpay',b.id,{sm:true,lbl:t('Pay','ادفع')+' '+T2(b.sup)})}</span>`})).join(''):`<div style="padding:8px 0">${H.note(t('All supplier bills are paid.','كل فواتير الموردين مدفوعة.'))}</div>`)
 +H.sec(t('Add a supplier bill','أضف فاتورة مورد'),`<div style="padding:12px 16px">${L.fld('bsup',t('Supplier','المورد'),{req:true,ph:t('e.g. Al Safi Dairy','مثال: ألبان الصافي')})}${L.fld('bamt',t('Amount (SAR)','المبلغ (ريال)'),{req:true,pre:'SAR',ltr:true,im:'decimal'})}${H.btns(L.ab(t('Add bill','أضف الفاتورة'),'billadd',null,{k:'sec'}))}</div>`)
 +(done.length?H.sec(t('Paid','مدفوعة'),H.rows(done.map(b=>({ic:'check',tone:'ok',t:esc(T2(b.sup)),s:b.paidTs?dt(b.paidTs):'',end:M(b.amt)})))):''); }});
ACT.billpay=id=>{ const b=S().hub.bills.find(x=>x.id===id); const left=r2(b.amt-b.paid); L.ui.bill=id; L.sheet(t('Pay supplier','الدفع للمورد'),`<p class="why" style="margin-bottom:10px">${esc(T2(b.sup))}</p>${L.fld('bpamt',t('Amount (SAR)','المبلغ (ريال)'),{req:true,pre:'SAR',ltr:true,im:'decimal',val:left.toFixed(2)})}${L.radio('bpm',[['bank',t('Bank transfer','تحويل بنكي')],['cash',t('Cash drawer','درج النقد'),t('Recorded in the cash book','يُسجل في دفتر النقدية')]],'bank',t('Pay with','الدفع بواسطة'))}<div class="btns" style="margin-top:12px">${L.ab(t('Record payment','سجّل الدفعة'),'billok',id)}${L.ab(t('Cancel','إلغاء'),'cardx',null,{k:'sec'})}</div>`); };
ACT.billok=id=>{ const s=S(); const b=s.hub.bills.find(x=>x.id===id); const left=r2(b.amt-b.paid); L.clearBad(); const amt=amtOf('bpamt'); const m=L.val('bpm')||'bank'; if(!(amt>0)||amt>left+0.001){ L.bad('bpamt',t(`Enter 0.01 to ${left.toFixed(2)}`,`أدخل من 0.01 إلى ${left.toFixed(2)}`)); L.focusBad(); return; } if(m==='cash'&&amt>cashBal()){ L.bad('bpamt',t(`Only ${cashBal().toFixed(2)} in the drawer`,`يوجد ${cashBal().toFixed(2)} فقط في الدرج`)); L.focusBad(); return; }
 b.paid=r2(b.paid+amt); b.paidTs=now(); b.lastPay=r2(amt); if(m==='cash') s.hub.cash.push({id:'K'+(++s.seq.cash),ts:now(),k:'sup',amt:r2(amt),m:'cash',note:b.sup}); L.closeSheet(); L.save(); L.rr(); toast(t(`Paid ${amt.toFixed(2)} · balance updated`,`دُفع ${amt.toFixed(2)} · تم تحديث الرصيد`)); };
ACT.billadd=()=>{ L.clearBad(); const sup=L.val('bsup'), amt=amtOf('bamt'); let ok=true; if(!sup){ L.bad('bsup',t('Enter the supplier','أدخل المورد')); ok=false; } if(!(amt>0)){ L.bad('bamt',t('Enter an amount above 0','أدخل مبلغًا أكبر من 0')); ok=false; } if(!ok){ L.focusBad(); return; } S().hub.bills.push({id:'B'+now(),sup:[sup,sup],amt:r2(amt),due:now()+7*DAY,paid:0}); L.save(); L.rr(); toast(t('Bill added · due in 7 days','أُضيفت الفاتورة · تستحق خلال 7 أيام')); };
L.def('cb.today',{v:null,noSeg:true,render:(c)=>{ const s=S(); const day=s.hub.cash.filter(e=>e.ts>=startToday()-86400000*0).sort((a,b)=>b.ts-a.ts); const cs=r2(day.filter(e=>e.k==='sale'&&e.m==='cash').reduce((a,e)=>a+e.amt,0)), card=r2(day.filter(e=>e.k==='sale'&&e.m!=='cash').reduce((a,e)=>a+e.amt,0)), out=r2(day.filter(e=>e.k==='exp'||e.k==='sup').reduce((a,e)=>a+e.amt,0));
 const lbl=e=>e.k==='open'?t('Opening float','رصيد افتتاحي'):e.k==='sale'?t('Sale','بيع')+' · '+({cash:t('cash','نقد'),mada:'mada',app:t('delivery app','تطبيق توصيل'),tab:t('on account','على الحساب')}[e.m]||e.m):e.k==='sup'?t('Supplier payment','دفعة لمورد'):t('Expense','مصروف')+' · '+catL(e.cat);
 return H.sec('',`<div class="card pad">${H.hero(t('Cash in drawer','النقد في الدرج'),M(cashBal()),t('Opening float + cash sales − cash paid out','الرصيد الافتتاحي + المبيعات النقدية − المدفوع نقدًا'))}</div>`,{raw:true})+H.kpis([[t('Cash sales','مبيعات نقدية'),M(cs,'',0)],[t('Card & apps','بطاقات وتطبيقات'),M(card,'',0)],[t('Paid out','مدفوع'),M(out,'',0)]])
 +`<div class="btns" style="margin:0 16px 16px">${H.btn(t('Sale','بيع'),{go:'cb.sale',ic:'plus'})}${H.btn(t('Expense','مصروف'),{go:'cb.expense',ic:'minus',k:'sec'})}${H.btn(t('Supplier','مورد'),{go:'bh.payments',ic:'wallet',k:'sec'})}</div>`
 +H.sec(t('Today’s entries','قيود اليوم'),day.length?H.rows(day.map(e=>({ic:e.k==='sale'?'cash':e.k==='open'?'lock':'receipt',tone:e.k==='sale'||e.k==='open'?'ok':'',t:lbl(e),s:`${tm(e.ts)} · ${esc(T2(e.note||['','']))}`,end:`<span class="lv-row-e">${M(e.k==='sale'||e.k==='open'?e.amt:-e.amt)}${e.k!=='open'?`<button type="button" class="ib flat" data-act="cbdel" data-arg="${e.id}" aria-label="${t('Undo entry','تراجع عن القيد')}">${I('trash',18)}</button>`:''}</span>`}))):`<div style="padding:8px 0">${H.note(t('No entries yet today.','لا قيود اليوم بعد.'))}</div>`)
 +H.sec('',H.rows([{ic:'lock',tone:'brand',t:t('Close the day','إغلاق اليوم'),s:t('Count the drawer (prototype screen)','عدّ الدرج (شاشة نموذجية)'),go:'bh.close'}])); }});
ACT.cbdel=id=>{ const s=S(); const e=s.hub.cash.find(x=>x.id===id); s.hub.cash=s.hub.cash.filter(x=>x.id!==id); if(e&&e.ref) s.hub.exp=s.hub.exp.filter(x=>x.id!==e.ref); L.save(); L.rr(); toast(t('Entry removed','أُزيل القيد')); };
L.ui.cbm='cash';
L.def('cb.sale',{v:null,noSeg:true,render:(c)=>H.sec('',`<div style="padding:14px 16px">${L.fld('samt',t('Sale amount (SAR, incl. VAT)','مبلغ البيع (ريال، شامل الضريبة)'),{req:true,pre:'SAR',ltr:true,im:'decimal',ph:'0.00'})}</div>`)+H.sec(t('Paid by','طريقة الدفع'),`<div style="padding:12px 0 2px">${L.chipsA('cbm',[['cash',t('Cash','نقد')],['mada','mada'],['app',t('Delivery app','تطبيق توصيل')],['tab',t('On account','على الحساب')]],L.ui.cbm,t('Paid by','طريقة الدفع'))}</div>`)+H.sec('',`<div style="padding:12px 16px">${L.fld('snote',t('Note (optional)','ملاحظة (اختياري)'),{ph:t('e.g. Table 4','مثال: طاولة 4'),max:40})}</div>`)+H.btns(L.ab(t('Record sale','سجّل البيع'),'ssave'))});
