ACT.ssave=()=>{ L.clearBad(); const amt=amtOf('samt'); if(!(amt>0)||amt>50000){ L.bad('samt',t('Enter an amount between 0.01 and 50,000','أدخل مبلغًا بين 0.01 و 50,000')); L.focusBad(); return; } const s=S(); const n=L.val('snote'); s.hub.cash.push({id:'K'+(++s.seq.cash),ts:now(),k:'sale',amt:r2(amt),m:L.ui.cbm,note:[n||'—',n||'—']}); L.save(); go('cb.today'); setTimeout(()=>toast(t(`Sale recorded · ${amt.toFixed(2)}`,`سُجل البيع · ${amt.toFixed(2)}`)),80); };
