['b.order','b.invoice','b.pod','b.track'].forEach(id=>{ const d=MF.SCR[id]; ['sales','acct','mgr'].forEach(r=>{ if(!d.r.includes(r)) d.r.push(r); }); });
(function(){ const d=MF.SCR['b.order']; const r=d.render; d.render=c=>{ const o=r(c); if(MF.ROLES[c.role].grp==='staff'&&o&&o.b){ return o.b; } return o; }; })();
const CUST=L.CUST=[{id:'alwadi',n:['Al Wadi Restaurant','مطعم الوادي'],tier:['Gold','ذهبي'],live:true},{id:'kunafa',n:['Bayt Al Kunafa','بيت الكنافة'],tier:['Silver','فضي'],bal:4210,limit:8000},{id:'nakheel',n:['Shawarma Al Nakheel','شاورما النخيل'],tier:['Silver','فضي'],bal:6900,limit:7000,risk:true},{id:'qahwa',n:['Qahwat Al Hay','قهوة الحي'],tier:['Bronze','برونزي'],bal:0,limit:0,isNew:true},{id:'bahr',n:['Mataam Al Bahr','مطعم البحر'],tier:['Gold','ذهبي'],bal:2300,limit:20000}];
const cst=id=>CUST.find(x=>x.id===id)||CUST[0];
const cfin=cu=>{ if(cu.live){ const cr=L.credit(); return {bal:cr.used,limit:cr.limit,od:cr.overdue}; } return {bal:cu.bal,limit:cu.limit,od:cu.risk?1200:0}; };
L.ui.cf='all';
const custList=(q)=>{ const f=L.ui.cf; const A=CUST.filter(cu=>(f==='all'||(f==='risk'&&(cu.risk||cfin(cu).od>0))||(f==='new'&&cu.isNew))&&(!q||T2(cu.n).toLowerCase().includes(q.toLowerCase())||cu.n[0].toLowerCase().includes(q.toLowerCase()))); return A.length?H.sec('',H.rows(A.map(cu=>{ const fi=cfin(cu); return {av:T2(cu.n).slice(0,1),t:T2(cu.n),s:`${T2(cu.tier)} · ${t('balance','الرصيد')} ${M(fi.bal,'',0)}${fi.limit?' / '+M(fi.limit,'',0):''}`,pill:fi.od>0?['bad',t('Overdue','متأخر')]:cu.isNew?['info',t('New','جديد')]:null,go:'c.360',q:{cust:cu.id}}; }))):H.empty('users',t('No customers match','لا عملاء مطابقون'),''); };
L.def('s.customers',{v:null,noSeg:true,render:(c)=>`<div class="search" role="search">${I('search',20)}<label class="vh" for="csq">${t('Search customers','ابحث في العملاء')}</label><input id="csq" type="search" data-live="cust" data-tgt="cres" autocomplete="off" placeholder="${t('Customer name','اسم العميل')}"></div>`+L.chipsA('cf',[['all',t('All','الكل')],['risk',t('At risk','معرّض للخطر')],['new',t('New','جدد')]],L.ui.cf,t('Filter','تصفية'))+`<div id="cres">${custList('')}</div>`});
