L.def('c.360',{v:[['overview',['Overview','نظرة عامة']],['orders',['Orders','الطلبات']],['finance',['Finance','المالية']],['support',['Support','الدعم']],['activity',['Activity','النشاط']]],segLabel:['Section','القسم'],t:()=>T2(cst(qp('cust')||'alwadi').n),render:(c)=>{ const cu=cst(qp('cust')||'alwadi'); const s=S(); const fi=cfin(cu); const acts=s.field.acts.filter(a=>(a.cust||'alwadi')===cu.id);
 let h=H.sec('',`<div class="card pad acct"><span class="av" aria-hidden="true">${T2(cu.n).slice(0,1)}</span><span style="flex:1;min-width:0"><h2>${T2(cu.n)}</h2><span class="s">${T2(cu.tier)} · ${t('Riyadh North · Faisal','شمال الرياض · فيصل')}</span></span>${fi.od>0?H.pill('bad',t('Overdue','متأخر')):H.pill('ok',t('Good standing','وضع جيد'))}</div>`,{raw:true});
 const ords=cu.live?s.orders:[]; const tks=cu.live?s.tickets:[];
 if(c.v==='overview'){ const d30=ords.filter(o=>Date.now()-o.ts<30*DAY); h+=H.kpis([[t('Orders · 30 days','الطلبات · 30 يومًا'),N(cu.live?d30.length:3)],[t('Avg basket','متوسط السلة'),M(cu.live&&d30.length?d30.reduce((a,o)=>a+L.tot(o).tot,0)/d30.length:2650,'',0)],[t('Credit used','الائتمان المستخدم'),fi.limit?Math.round(fi.bal/fi.limit*100)+'%':'—','',fi.limit&&fi.bal/fi.limit>.9?'warn':''],[t('Open requests','طلبات مفتوحة'),N(tks.filter(x=>x.st!=='resolved').length)]]);
  if(cu.live){ const b=L.basket(); if(b.length) h+=H.sec(t('Below par','أقل من الحد'),b.map(x=>H.row({g:P0()[x.sku].g,t:pn(x.sku),s:t(`${x.need} below par`,`أقل من الحد بـ ${x.need}`)})).join('')); }
  h+=H.sec(t('Last activity','آخر نشاط'),acts.length?H.rows(acts.slice(0,3).map(a=>({ic:a.k==='visit'?'visit':a.k==='order'?'cart':'edit',t:esc(T2(a.txt)),s:`${a.who} · ${ago(a.ts)}`}))):`<div style="padding:8px 0">${H.note(t('No activity logged yet.','لا نشاط مسجل بعد.'))}</div>`); }
 if(c.v==='orders') h+=ords.length?H.sec('',H.rows(ords.map(o=>L.oRow(o)))):H.empty('box',t('No orders in this demo','لا طلبات في هذا العرض'),'');
 if(c.v==='finance') h+=H.kpis([[t('Balance','الرصيد'),M(fi.bal,'',0)],[t('Limit','الحد'),M(fi.limit,'',0)],[t('Overdue','متأخر'),M(fi.od,'',0),'',fi.od?'bad':'']])+(cu.live?H.sec(t('Invoices','الفواتير'),H.rows(s.invoices.map(L.invRow))):'');
 if(c.v==='support') h+=tks.length?H.sec('',H.rows(tks.map(x=>({ic:'msg',tone:x.st==='resolved'?'ok':'brand',t:`${LTR(x.id)} · ${L.tkTopic(x.topic)}`,s:ago(x.ts),pill:L.tkPill(x),go:'cc.case',q:{id:x.id}}))))+H.note(t('Salespeople are copied on requests and can add internal notes.','يُنسخ المندوب على الطلبات ويمكنه إضافة ملاحظات داخلية.')):H.empty('inbox',t('No requests','لا طلبات'),'');
 if(c.v==='activity') h+=acts.length?H.sec('',H.tl(acts.map(a=>['done',esc(T2(a.txt)),`${a.who} · ${dt(a.ts,{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}`]))):H.empty('hist',t('No activity yet','لا نشاط بعد'),'');
 return {b:h,dock:c.role==='sales'?`${L.ab(t('Log visit','سجّل زيارة'),'visit',cu.id,{k:'sec',ic:'visit'})}${H.btn(t('New order','طلب جديد'),{go:'s.order',q:{cust:cu.id},ic:'cart'})}`:L.ab(t('Add note','أضف ملاحظة'),'visit',cu.id,{k:'sec',ic:'edit',block:true})}; }});
