 return H.sec(t('Products','المنتجات'),Object.keys(P0()).map(k=>MF.prow(k,{end:P0()[k].stock==='out'?H.pill('bad',t('Out','نفد')):L.stepA('sq',k,sc[k]||0,pn(k))})).join(''))+H.sec(t('Summary','الملخص'),H.kv([[t('Subtotal (excl. VAT)','المجموع الفرعي (قبل الضريبة)'),M(T.sub)],[t('VAT 15%','الضريبة 15%'),M(T.vat)],[t('Total','الإجمالي'),M(T.tot),'tot']]))
