ACT.sordgo=cuId=>{ const s=S(); const sc=s.field.scart; if(!Object.keys(sc).length) return; const cu=cst(cuId); let msg; if(cu.live){ const id=String(++s.seq.order); const o={id,ts:Date.now(),by:'sales',branch:'Olaya',items:Object.assign({},sc),pay:'credit',pts:0,st:'ok'}; L.earn(o); s.orders.unshift(o); L.notify('box',[`Faisal (sales) placed order #${id} for you`,`طلب فيصل (المندوب) الطلب ‎#${id} لك`],['b.order',{id}]); msg=t(`Order #${id} placed for ${cu.n[0]}`,`تم الطلب ‎#${id} لـ ${cu.n[1]}`); } else msg=t(`Order sent for ${cu.n[0]} (sample)`,`أُرسل الطلب لـ ${cu.n[1]} (عينة)`); const T=L.tot({items:sc}); s.field.acts.unshift({ts:Date.now(),cust:cu.id,who:'Faisal',k:'order',txt:[`Order placed · ${T.tot.toFixed(2)}`,`طلب · ${T.tot.toFixed(2)}`]}); s.field.scart={}; L.save(); go('c.360',{cust:cu.id,v:'activity'}); setTimeout(()=>toast(msg),80); };

