ACT.vq=a=>{ const [k,d]=a.split(':'); const v=S().van; const cur=v.cart[k]||0; const nq=Math.max(0,cur+Number(d)); if(nq>cur&&nq>v.stock[k]){ toast(t(`Only ${v.stock[k]} on the van`,`يوجد ${v.stock[k]} فقط في الفان`)); return; } if(nq) v.cart[k]=nq; else delete v.cart[k]; L.save(); L.rr(); };
