L.def('v.queue',{v:null,noSeg:true,render:()=>{ const q=S().van.inv.filter(i=>i.queued); const done=S().van.inv.filter(i=>!i.queued); return (q.length?H.sec(t('Waiting to sync','بانتظار المزامنة'),H.rows(q.map(i=>({ic:'sync',tone:'warn',t:`${LTR(i.id)} · ${M(i.tot)}`,s:tm(i.ts)})))):H.empty('ok',t('Everything is synced','كل شيء متزامن'),t('Invoices issued offline wait here.','تنتظر هنا الفواتير الصادرة دون اتصال.')))+(done.length?H.sec(t('Synced today','تمت مزامنتها اليوم'),H.rows(done.map(i=>({ic:'check',tone:'ok',t:`${LTR(i.id)} · ${M(i.tot)}`,s:tm(i.ts),go:'v.issued',q:{id:i.id}})))):'')+(q.length?H.btns(L.ab(t('Sync now','زامن الآن'),'vsync',null,{dis:S().offline})):''); }});
