const stop=id=>S().route.find(x=>x.id===id);
const sPill=x=>({done:['ok',t('Delivered','تم التسليم')],next:['info',t('Next','التالي')],todo:['',t('Later','لاحقًا')],failed:['bad',t('Not delivered','لم يُسلّم')]}[x.st]);
L.def('d.route',{render:()=>{ const R=S().route; const dn=R.filter(x=>x.st==='done').length; const nx=R.find(x=>x.st==='next')||R.find(x=>x.st==='todo');
 return H.sec('',`<div class="card pad">${H.hero(t('Stops delivered','المحطات المسلّمة'),`${dn} / ${R.length}`,nx?t('Next:','التالي:')+' '+T2(nx.n):t('Route complete','اكتمل المسار'))}${H.meter([[dn/R.length*100,'brand']],t(`${dn} of ${R.length} delivered`,`${dn} من ${R.length} سُلّمت`))}</div>`,{raw:true})+H.sec(t('Stops','المحطات'),H.rows(R.map((x,i)=>({av:String(i+1),t:T2(x.n),s:`${T2(x.addr)} · ${t('order','طلب')} #${x.order}${x.cold?' · '+t('chilled','مبرد'):''}`,pill:sPill(x),go:'d.stop',q:{id:x.id}}))))+(nx?H.btns(H.btn(t('Open next stop','افتح المحطة التالية'),{go:'d.stop',q:{id:nx.id},ic:'route'})):''); }});
L.def('d.stop',{v:null,noSeg:true,t:()=>{ const x=stop(qp('id'))||S().route.find(r=>r.st==='next')||S().route[0]; return t('Stop','المحطة')+' '+(S().route.indexOf(x)+1)+' · '+T2(x.n); },render:()=>{ const x=stop(qp('id'))||S().route.find(r=>r.st==='next')||S().route[0];
 let h=H.sec('',H.kv([[t('Status','الحالة'),H.pill(...sPill(x))],[t('Address','العنوان'),T2(x.addr)],[t('Order','الطلب'),LTR('#'+x.order)],[t('Receiving','الاستلام'),t('6–11 AM · back door','6–11 ص · الباب الخلفي')]]));
 h+=H.sec(t('Items to hand over','الأصناف للتسليم'),Object.entries(x.items).map(([k,q])=>H.row({g:P0()[k].g,t:pn(k),end:`<span class="num">× ${q}</span>`})).join(''))+(x.cold?H.note(t('Chilled items: check temperature at hand-over.','أصناف مبردة: افحص الحرارة عند التسليم.'),'thermo'):'');
 if(x.st==='done') h+=H.alert('ok',t('Delivered','تم التسليم'),`${esc(x.rcv||t('Received','مستلم'))} · ${x.ts?tm(x.ts):''}`);
 if(x.st==='failed') h+=H.alert('bad',t('Not delivered','لم يُسلّم'),esc(T2(x.why||['',''])),{act:L.ab(t('Try again','حاول مجددًا'),'sretry',x.id,{sm:true,k:'sec'})});
 h+=H.btns(L.ab(t('Navigate','الملاحة'),'nav0',null,{k:'sec',ic:'map'}),L.ab(t('Call','اتصل'),'call',null,{k:'sec',ic:'phone'}));
 return x.st==='done'?h:{b:h,dock:`${H.btn(t('Can’t deliver','تعذّر التسليم'),{k:'sec',go:'d.failed',q:{id:x.id}})}${H.btn(t('Deliver','سلّم'),{go:'d.pod',q:{id:x.id},ic:'check'})}`}; }});
