L.ui.podm='sig';
L.def('d.pod',{v:null,noSeg:true,render:()=>{ const x=stop(qp('id'))||S().route.find(r=>r.st==='next'); if(!x) return H.empty('ok',t('No stop selected','لا محطة محددة'),'',H.btns(H.btn(t('Route','المسار'),{go:'d.route'})));
 const m=L.ui.podm; let h=H.sec('',`<div style="padding:12px 16px">${L.fld('rcv',t('Received by','المستلم'),{req:true,ph:t('Name of the person receiving','اسم المستلم'),val:L.ui.rcv||'',ac:'name'})}</div>`);
 h+=H.sec(t('Confirm with','التأكيد بواسطة'),`<div style="padding:12px 0 2px">${L.chipsA('podm',[['sig',t('Signature','التوقيع')],['otp',t('Customer code','رمز العميل')]],m,t('Confirmation method','طريقة التأكيد'))}</div><div style="padding:0 16px 14px">${m==='sig'?`<div data-f="sig"><canvas class="lv-sig" width="640" height="220" role="img" aria-label="${t('Signature pad — draw with your finger','لوحة التوقيع — ارسم بإصبعك')}"></canvas><span class="err" hidden>${I('alert',16)}<span></span></span></div><div class="btns" style="margin-top:8px">${L.ab(t('Clear','امسح'),'sigclr',null,{k:'sec',sm:true})}${L.ab(t('Use code instead','استخدم الرمز بدلًا'),'podm','otp',{k:'ghost',sm:true})}</div>`:L.fld('otp',t('4-digit code from the customer','الرمز المكون من 4 أرقام من العميل'),{req:true,ltr:true,im:'numeric',max:4,hint:t(`Sample code for this stop: ${x.otp}`,`الرمز التجريبي لهذه المحطة: ${x.otp}`)})}</div>`);
 if(x.cold) h+=H.sec('',L.check('temp',t('Temperature checked (chilled 0–4 °C)','فُحصت الحرارة (مبرد 0–4 °م)'),false,t('Required for chilled items','مطلوب للأصناف المبردة')));
 h+=H.sec('',`<div style="padding:12px 16px">${H.btns(L.ab(t('Add photo (simulated)','أضف صورة (محاكاة)'),'podph',null,{k:'sec',sm:true,ic:'camera'}))}<p class="why">${L.ui.podph?t('1 photo attached','أُرفقت صورة'):t('Optional','اختياري')}</p></div>`);
 return {b:h,dock:L.ab(t('Confirm delivery','أكّد التسليم'),'podok',x.id,{block:true,ic:'check'})}; }});
ACT.podm=v=>{ const r=document.querySelector('[name=rcv]'); if(r) L.ui.rcv=r.value; L.ui.podm=v; L.ui.sig=false; L.rr(); };
ACT.sigclr=()=>{ const cv=document.querySelector('.lv-sig'); if(cv){ cv.getContext('2d').clearRect(0,0,cv.width,cv.height); } L.ui.sig=false; };
ACT.podph=()=>{ const r=document.querySelector('[name=rcv]'); if(r) L.ui.rcv=r.value; L.ui.podph=true; L.rr(); toast(t('Photo added','أُضيفت صورة')); };
L.post.push(c=>{ const cv=document.querySelector('.lv-sig'); if(!cv) return; const g=cv.getContext('2d'); g.lineWidth=4; g.lineCap='round'; g.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--c-text')||'#111'; let on=false; const pt=e=>{ const r=cv.getBoundingClientRect(); return [(e.clientX-r.left)*cv.width/r.width,(e.clientY-r.top)*cv.height/r.height]; };
 cv.addEventListener('pointerdown',e=>{ on=true; cv.setPointerCapture(e.pointerId); const [x,y]=pt(e); g.beginPath(); g.moveTo(x,y); e.preventDefault(); }); cv.addEventListener('pointermove',e=>{ if(!on) return; const [x,y]=pt(e); g.lineTo(x,y); g.stroke(); L.ui.sig=true; }); cv.addEventListener('pointerup',()=>{ on=false; }); });
ACT.podok=id=>{ L.clearBad(); const x=stop(id); const rcv=L.val('rcv'); let ok=true; if(!rcv){ L.bad('rcv',t('Enter who received it','أدخل اسم المستلم')); ok=false; }
 if(L.ui.podm==='sig'&&!L.ui.sig){ const f=document.querySelector('[data-f=sig] .err'); if(f){ f.hidden=false; f.querySelector('span').textContent=t('Ask the customer to sign, or use their code','اطلب من العميل التوقيع أو استخدم رمزه'); } ok=false; }
 if(L.ui.podm==='otp'&&L.val('otp')!==x.otp){ L.bad('otp',t('That code doesn’t match','الرمز غير مطابق')); ok=false; }
 if(x.cold&&!L.val('temp')){ L.bad('temp',t('Confirm the temperature check','أكّد فحص الحرارة')); ok=false; }
 if(!ok){ L.focusBad(); toast(t('Check the highlighted fields','راجع الحقول المحددة')); return; }
 x.st='done'; x.ts=Date.now(); x.rcv=rcv; x.pod=L.ui.podm; L.ui.rcv=''; L.ui.sig=false; L.ui.podph=false; const nx=S().route.find(r=>r.st==='todo'); if(nx) nx.st='next'; L.save(); go(nx?'d.stop':'d.route',nx?{id:nx.id}:{}); setTimeout(()=>toast(t(`Delivered to ${rcv}`,`سُلّم إلى ${rcv}`)+(nx?' · '+t('next stop opened','فُتحت المحطة التالية'):'')),80); };
L.def('d.failed',{v:null,noSeg:true,render:()=>{ const x=stop(qp('id'))||S().route.find(r=>r.st==='next'); return H.sec(t('What happened?','ماذا حدث؟'),L.radio('fwhy',[['closed',t('Closed','مغلق')],['nobody',t('No one to receive','لا يوجد مستلم')],['refused',t('Refused','رفض الاستلام')],['addr',t('Can’t find the address','تعذر إيجاد العنوان')]],'',t('Reason','السبب'))+`<div data-f="fwhy" style="padding:0 16px"><span class="err" hidden>${I('alert',16)}<span></span></span></div>`)+H.sec('',`<div style="padding:12px 16px">${L.fld('fnote',t('Note (optional)','ملاحظة (اختياري)'),{ta:true})}</div>`)+H.btns(L.ab(t('Confirm & go to next stop','أكّد وانتقل للمحطة التالية'),'failok',x&&x.id)); }});
ACT.failok=id=>{ const w=L.val('fwhy'); if(!w){ const f=document.querySelector('[data-f=fwhy] .err'); if(f){ f.hidden=false; f.querySelector('span').textContent=t('Choose a reason','اختر سببًا'); } const r=document.querySelector('[name=fwhy]'); r&&r.focus(); return; } const x=stop(id); const W={closed:['Closed','مغلق'],nobody:['No one to receive','لا يوجد مستلم'],refused:['Refused','رفض الاستلام'],addr:['Can’t find the address','تعذر إيجاد العنوان']}; x.st='failed'; x.why=W[w]; const nx=S().route.find(r=>r.st==='todo'); if(nx) nx.st='next'; L.save(); go('d.route'); setTimeout(()=>toast(t('Marked as not delivered · dispatcher notified','عُلّم كغير مُسلّم · أُبلغ المرسل')),80); };
/* ---------- STAFF: storekeeper ---------- */
const pk=id=>S().picks.find(x=>x.id===id);
const pkPill=p=>({open:['warn',t('To pick','للتجهيز')],picking:['info',t('Picking','جارٍ التجهيز')],packed:['ok',t('Packed','مُعبأ')],dispatched:['',t('Dispatched','أُرسل')]}[p.st]);
const pkProg=p=>{ const need=p.lines.reduce((a,l)=>a+l.q,0), got=p.lines.reduce((a,l)=>a+Math.min(l.got,l.q),0); return [got,need]; };
L.def('k.lists',{v:null,noSeg:true,render:()=>{ const P=S().picks; const grp=(f,ttl)=>{ const A=P.filter(f); return A.length?H.sec(ttl,H.rows(A.map(p=>{ const [g,n]=pkProg(p); return {ic:'layers',tone:p.st==='packed'?'ok':'brand',t:`${LTR(p.id)} · ${t('Truck','شاحنة')} ${p.truck}`,s:`${t('Wave','الدفعة')} ${p.wave} · ${g}/${n} ${t('cases','كرتون')}`,pill:pkPill(p),go:p.st==='packed'?'k.dispatch':'k.pick',q:{id:p.id}}; }))):''; };
 return grp(p=>p.st==='open'||p.st==='picking',t('To pick','للتجهيز'))+grp(p=>p.st==='packed',t('Ready to dispatch','جاهز للإرسال'))+grp(p=>p.st==='dispatched',t('Dispatched today','أُرسل اليوم'))||H.empty('box',t('No pick lists','لا قوائم'),''); }});
L.def('k.pick',{v:null,noSeg:true,t:()=>{ const p=pk(qp('id'))||S().picks.find(x=>x.st==='open'||x.st==='picking')||S().picks[0]; return t('Pick · Truck','التجهيز · شاحنة')+' '+p.truck; },render:()=>{ const p=pk(qp('id'))||S().picks.find(x=>x.st==='open'||x.st==='picking')||S().picks[0]; const [g,n]=pkProg(p); const ro=p.st==='packed'||p.st==='dispatched';
 let h=H.sec('',`<div class="card pad">${H.hero(LTR(p.id),`${g} / ${n}`,t('cases picked','كرتون مُجهّز'))}${H.meter([[g/n*100,'brand']],t(`${g} of ${n} picked`,`${g} من ${n} مُجهّز`))}</div>`,{raw:true});
 h+=H.sec(t('Lines','البنود'),p.lines.map((l,i)=>H.row({g:P0()[l.sku].g,t:pn(l.sku),s:`${t('Bin','الموقع')} ${LTR(l.bin)} · ${t('need','المطلوب')} ${l.q}${l.cold?' · '+t('chilled','مبرد'):''}${l.short?' · <b class="neg">'+t(`short ${l.q-l.got}`,`نقص ${l.q-l.got}`)+'</b>':''}`,end:ro?H.pill(l.got>=l.q?'ok':'warn',`${l.got}/${l.q}`):l.got>=l.q?`<span class="lv-row-e">${H.pill('ok',t('Done','تم'))}${L.stepA('kq',p.id+'|'+i,l.got,pn(l.sku))}</span>`:`<span class="lv-row-e">${l.got?L.stepA('kq',p.id+'|'+i,l.got,pn(l.sku)):''}${L.ab(t('Scan','امسح'),'kscan',p.id+'|'+i,{sm:true,ic:'scan',lbl:t('Scan','امسح')+' '+pn(l.sku)})}${l.got<l.q&&!l.short?L.ab(t('Short','نقص'),'kshort',p.id+'|'+i,{sm:true,k:'ghost',lbl:t('Mark short','علّم كناقص')+' '+pn(l.sku)}):''}</span>`})).join(''));
 if(!ro) h+=H.btns(L.ab(t('Simulate a wrong scan','حاكِ مسحًا خاطئًا'),'kwrong',p.id,{k:'sec',sm:true}));
 return ro?h+H.alert('ok',t('Packed','مُعبأ'),t('Ready for dispatch.','جاهز للإرسال.'),{act:H.btn(t('Go to dispatch','انتقل للإرسال'),{sm:true,go:'k.dispatch',q:{id:p.id}})}):{b:h,dock:L.ab(t('Complete pick','أكمل التجهيز'),'kdone',p.id,{block:true,dis:g===0})}; }});
const pl=a=>{ const [id,i]=a.split('|'); const p=pk(id); return [p,p.lines[Number(i)]]; };
ACT.kscan=a=>{ const [p,l]=pl(a); l.got=l.q; p.st='picking'; L.save(); L.rr(); toast(t(`Scanned ${pn(l.sku)} · ${l.q} picked`,`مُسح ${pn(l.sku)} · ${l.q} مُجهّز`)); };
ACT.kq=a=>{ const [id,i,d]=a.split(/[|:]/); const p=pk(id), l=p.lines[Number(i)]; l.got=Math.max(0,Math.min(l.q,l.got+Number(d))); p.st='picking'; L.save(); L.rr(); };
